export function getMiroirReferences(): string[] {
  return Object.keys(MIROIR_INDEX);
}

export function getMiroirTheme(ref: string): string[] | undefined {
  return MIROIR_INDEX[ref]?.theme;
}

export function hasMiroir(ref: string): boolean {
  return ref in MIROIR_INDEX;
}

export function getMiroirCount(): number {
  return Object.keys(MIROIR_INDEX).length;
}

// Get a random miroir reference
export function getRandomMiroir(): string {
  const refs = Object.keys(MIROIR_INDEX);
  return refs[Math.floor(Math.random() * refs.length)];
}
